import React, { useState, useEffect, useRef } from 'react';
import './Catalogue.css';

function Nouveautes({ allerVers, utilisateur }) {
  const [musiques, setMusiques] = useState([]);
  const [chargement, setChargement] = useState(true);
  const [lecteurActif, setLecteurActif] = useState(null);
  const audioRef = useRef(null);

  useEffect(() => {
    fetch('/api/musiques/nouveautes')
      .then(res => res.json())
      .then(data => {
        setMusiques(data.musiques);
        setChargement(false);
      })
      .catch(() => setChargement(false));
  }, []);

  const jouerExtrait = (musique) => {
    if (lecteurActif === musique.id) {
      audioRef.current.pause();
      setLecteurActif(null);
    } else {
      if (audioRef.current) audioRef.current.pause();
      audioRef.current = new Audio(musique.fichier_url);
      audioRef.current.play();
      setLecteurActif(musique.id);
      setTimeout(() => {
        if (audioRef.current) audioRef.current.pause();
        setLecteurActif(null);
      }, 20000);
    }
  };

  return (
    <div className="catalogue-page">
      <header className="header">
        <div className="logo" onClick={() => allerVers('accueil')}>🎵 Varim Music</div>
        <nav className="nav">
          <a href="#" onClick={() => allerVers('accueil')}>Accueil</a>
          <a href="#" onClick={() => allerVers('catalogue')}>Catalogue</a>
          <a href="#" className="actif">Nouveautés</a>
          <a href="#" onClick={() => allerVers('topventes')}>Top Ventes</a>
        </nav>
        <div className="auth-buttons">
          {utilisateur ? (
            <>
              <span className="user-prenom">👋 {utilisateur.prenom}</span>
              {utilisateur.role === 'artiste' && (
                <button className="btn-dashboard" onClick={() => allerVers('upload')}>+ Publier</button>
              )}
              <button className="btn-login" onClick={() => {
                localStorage.removeItem('token');
                localStorage.removeItem('utilisateur');
                allerVers('accueil');
              }}>Déconnexion</button>
            </>
          ) : (
            <>
              <button className="btn-login" onClick={() => allerVers('login')}>Connexion</button>
              <button className="btn-register" onClick={() => allerVers('register')}>S'inscrire</button>
            </>
          )}
        </div>
      </header>

      <div className="catalogue-contenu">
        <h1 className="catalogue-titre">🆕 Nouveautés</h1>
        <p style={{color: '#a0aec0', marginBottom: '30px'}}>Les dernières musiques ajoutées</p>

        {chargement ? (
          <div className="chargement">Chargement...</div>
        ) : musiques.length === 0 ? (
          <div className="vide">Aucune musique disponible.</div>
        ) : (
          <div className="grille-musiques">
            {musiques.map(musique => (
              <div key={musique.id} className="carte-musique">
                <div className="carte-pochette">
                  {musique.pochette_url ? (
                    <img src={musique.pochette_url} alt={musique.titre} />
                  ) : (
                    <div className="pochette-defaut">🎵</div>
                  )}
                  <div className="carte-type">{musique.type}</div>
                </div>
                <div className="carte-infos">
                  <h3 className="carte-titre">{musique.titre}</h3>
                  <p className="carte-artiste" style={{cursor:'pointer'}} onClick={() => allerVers('profil_' + musique.artiste_id)}>
  🎤 {musique.nom_artiste}
</p>
                  <p className="carte-genre">🎸 {musique.genre}</p>
                  <p className="carte-prix">{musique.prix} FCFA</p>
                </div>
                <div className="carte-actions">
                  {musique.type === 'album' ? (
                    <button className="btn-extrait" onClick={() => allerVers('album_' + musique.id)}>
                      👁 Voir l'album
                    </button>
                  ) : (
                    <button
                      className={`btn-extrait ${lecteurActif === musique.id ? 'en-lecture' : ''}`}
                      onClick={() => jouerExtrait(musique)}
                    >
                      {lecteurActif === musique.id ? '⏸ Stop' : '▶ Extrait 20s'}
                    </button>
                  )}
                  <button className="btn-acheter" onClick={() => allerVers('achat_' + musique.id)}>
                    🛒 Acheter
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

export default Nouveautes;
